ALTER POLICY "announcements_staff_insert" ON "announcements" TO public WITH CHECK (exists (select 1 from staff_roles s where s.user_id = current_setting('app.user_id', true) and s.role in ('staff', 'admin')));--> statement-breakpoint
ALTER POLICY "announcements_staff_update" ON "announcements" TO public USING (exists (select 1 from staff_roles s where s.user_id = current_setting('app.user_id', true) and s.role in ('staff', 'admin'))) WITH CHECK (exists (select 1 from staff_roles s where s.user_id = current_setting('app.user_id', true) and s.role in ('staff', 'admin')));--> statement-breakpoint
ALTER POLICY "announcements_staff_delete" ON "announcements" TO public USING (exists (select 1 from staff_roles s where s.user_id = current_setting('app.user_id', true) and s.role in ('staff', 'admin')));